function zonedParts(date, timeZone) {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
  const bag = {};
  for (const p of fmt.formatToParts(date)) {
    if (p.type !== "literal") bag[p.type] = p.value;
  }
  return {
    year: Number(bag.year),
    month: Number(bag.month),
    day: Number(bag.day),
    hour: Number(bag.hour),
    minute: Number(bag.minute),
    second: Number(bag.second),
  };
}

function pad(n) { return String(n).padStart(2, "0"); }
function ymdOf(p) { return `${p.year}-${pad(p.month)}-${pad(p.day)}`; }

function offsetMs(date, timeZone) {
  const p = zonedParts(date, timeZone);
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
  return asUtc - date.getTime();
}

function wallTimeToUtc(year, month, day, hour, minute, second, timeZone) {
  const desired = Date.UTC(year, month - 1, day, hour, minute, second);
  let utc = desired;
  for (let i = 0; i < 3; i++) {
    utc = desired - offsetMs(new Date(utc), timeZone);
  }
  return new Date(utc);
}

function localDate(date, timeZone) {
  return ymdOf(zonedParts(date, timeZone));
}

function addCalendarDays(ymd, days) {
  const [y, m, d] = ymd.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d + days));
  return `${dt.getUTCFullYear()}-${pad(dt.getUTCMonth()+1)}-${pad(dt.getUTCDate())}`;
}

function startOfLocalDay(reference, timeZone) {
  const p = zonedParts(reference, timeZone);
  return wallTimeToUtc(p.year, p.month, p.day, 0, 0, 0, timeZone);
}

function matches(date, timeZone, y, m, d, h, min) {
  const p = zonedParts(date, timeZone);
  return p.year === y && p.month === m && p.day === d && p.hour === h && p.minute === min && p.second === 0;
}

function instantsForLocal(ymd, hour, minute, timeZone) {
  const [y, m, d] = ymd.split("-").map(Number);
  const nominal = Date.UTC(y, m - 1, d, hour, minute, 0);
  const found = new Set();
  for (let offsetMin = -14 * 60; offsetMin <= 14 * 60; offsetMin += 1) {
    const utc = nominal - offsetMin * 60_000;
    const date = new Date(utc);
    if (matches(date, timeZone, y, m, d, hour, minute)) found.add(date.toISOString());
  }
  return [...found].sort();
}

function mostRecent(reference, hour, timeZone) {
  const ymd = localDate(reference, timeZone);
  const today = instantsForLocal(ymd, hour, 0, timeZone).filter(s => new Date(s) <= reference);
  if (today.length) return today[today.length - 1];
  const prev = addCalendarDays(ymd, -1);
  const yest = instantsForLocal(prev, hour, 0, timeZone).filter(s => new Date(s) <= reference);
  return yest[yest.length - 1];
}

// start of day checks
const cases = [
  ["UTC", "2026-03-15T12:00:00.000Z", "2026-03-15T00:00:00.000Z"],
  ["Asia/Tokyo", "2026-03-15T12:00:00.000Z", "2026-03-14T15:00:00.000Z"], // Mar 15 21:00 JST, day started Mar 14 15:00Z
  ["Asia/Tokyo", "2026-03-15T15:00:00.000Z", "2026-03-15T15:00:00.000Z"], // exactly Mar 16 00:00 JST
  ["Asia/Kolkata", "2026-03-15T12:00:00.000Z", "2026-03-14T18:30:00.000Z"],
  ["Asia/Kathmandu", "2026-03-15T12:00:00.000Z", "2026-03-14T18:15:00.000Z"],
  ["America/New_York", "2026-03-15T15:00:00.000Z", "2026-03-15T04:00:00.000Z"], // EDT
  ["America/New_York", "2026-01-15T15:00:00.000Z", "2026-01-15T05:00:00.000Z"], // EST
  ["America/New_York", "2026-03-08T07:30:00.000Z", "2026-03-08T05:00:00.000Z"], // spring forward day, still EST at midnight, DST at 07:00Z
  ["America/New_York", "2026-11-01T06:30:00.000Z", "2026-11-01T04:00:00.000Z"], // fall back day midnight was EDT
  ["Australia/Lord_Howe", "2026-01-15T12:00:00.000Z", null],
  ["Pacific/Chatham", "2026-01-15T12:00:00.000Z", null],
];
for (const [z, iso, expected] of cases) {
