  const ok = p.hour === 0 && p.minute === 0 && p.second === 0 && localDate(new Date(iso), z) === ymdOf(p);
  console.log(ok ? "OK" : "BAD", z, iso, "->", got, "expected", expected, "local", JSON.stringify(p));
}

// digest windows
function window(hour, iso, tz) {
  const end = mostRecent(new Date(iso), hour, tz);
  const endYmd = localDate(new Date(end), tz);
  const startYmd = addCalendarDays(endYmd, -1);
  const starts = instantsForLocal(startYmd, hour, 0, tz);
