interface ZoneParts {
  readonly year: number;
  readonly month: number;
  readonly day: number;
  readonly hour: number;
  readonly minute: number;
  readonly second: number;
}

/** Throws RangeError when `timeZone` is not an IANA name `Intl` accepts. */
export function assertValidTimeZone(timeZone: string): void {
  try {
    Intl.DateTimeFormat("en-US", { timeZone });
  } catch (error) {
    throw new RangeError(
      error instanceof Error ? error.message : `Unknown time zone: ${timeZone}`,
    );
  }
}

function zoneParts(date: Date, timeZone: string): ZoneParts {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
  const bag: Record<string, string> = {};
  for (const part of fmt.formatToParts(date)) {
    if (part.type !== "literal") bag[part.type] = part.value;
  }

  let year = Number(bag.year);
  let month = Number(bag.month);
  let day = Number(bag.day);
  let hour = Number(bag.hour);
  // A few ICU builds report midnight as 24:00 on the previous calendar day.
  if (hour === 24) {
    hour = 0;
    const rolled = shiftCalendarDate(year, month, day, 1);
    year = rolled.year;
    month = rolled.month;
    day = rolled.day;
  }

  return {
    year,
    month,
    day,
    hour,
    minute: Number(bag.minute),
    second: Number(bag.second),
  };
}

function formatYmd(year: number, month: number, day: number): string {
  const pad = (value: number, width: number) => String(value).padStart(width, "0");
  return `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}`;
}

function shiftCalendarDate(
  year: number,
  month: number,
  day: number,
  days: number,
): { year: number; month: number; day: number } {
  const shifted = new Date(Date.UTC(year, month - 1, day + days));
  return {
    year: shifted.getUTCFullYear(),
    month: shifted.getUTCMonth() + 1,
    day: shifted.getUTCDate(),
  };
}

/** Offset of `timeZone` at `date`, in milliseconds: local = utc + offset. */
function offsetMs(date: Date, timeZone: string): number {
  const parts = zoneParts(date, timeZone);
  const asUtc = Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour,
    parts.minute,
    parts.second,
  );
  return asUtc - date.getTime();
}

/**
 * UTC instant of a wall-clock time in `timeZone`. Two offset corrections
 * cover a DST transition; a gap (the wall time never occurs) snaps to the
 * instant the clock jumps to, which callers detect by re-reading the parts.
 */
function wallTimeToUtc(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  second: number,
  timeZone: string,
): Date {
  const desired = Date.UTC(year, month - 1, day, hour, minute, second);
  let utc = desired;
  for (let i = 0; i < 3; i += 1) {
    utc = desired - offsetMs(new Date(utc), timeZone);
  }
  return new Date(utc);
}

function sameWallTime(date: Date, timeZone: string, parts: ZoneParts): boolean {
  const actual = zoneParts(date, timeZone);
  return (
    actual.year === parts.year &&
    actual.month === parts.month &&
    actual.day === parts.day &&
    actual.hour === parts.hour &&
    actual.minute === parts.minute &&
    actual.second === parts.second
  );
}

/**
 * Every UTC instant at which `timeZone` reads that wall time. Empty when the
 * clock skips it (spring forward). Two entries when the clock repeats it
 * (fall back). Ordered earliest first.
 */
function instantsOfWallTime(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  second: number,
  timeZone: string,
): Date[] {
  const wanted: ZoneParts = { year, month, day, hour, minute, second };
  const primary = wallTimeToUtc(year, month, day, hour, minute, second, timeZone);
  const found = new Map<number, Date>();
  const consider = (date: Date) => {
    if (!sameWallTime(date, timeZone, wanted)) return;
    found.set(date.getTime(), date);
  };

  consider(primary);
  // Folds are at most a couple of hours. Probe both sides of the primary hit.
  for (const deltaMin of [-120, -90, -60, -30, 30, 60, 90, 120]) {
    consider(new Date(primary.getTime() + deltaMin * 60_000));
  }

  return [...found.values()].sort((a, b) => a.getTime() - b.getTime());
}

