export function localHour(date: Date, timeZone: string): number {
  return zoneParts(date, timeZone).hour;
}

/** `YYYY-MM-DD` of `value` on the calendar in `timeZone`. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const parts = zoneParts(parseIso(value), timeZone);
  return formatYmd(parts.year, parts.month, parts.day);
}

