 * UTC instant at which the calendar day in `timeZone` that contains
 * `reference` began (local midnight).
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const parts = zoneParts(reference, timeZone);
  const midnight = instantsOfWallTime(
    parts.year,
    parts.month,
    parts.day,
    0,
    0,
    0,
    timeZone,
  );
  const instant =
    midnight[0] ?? wallTimeToUtc(parts.year, parts.month, parts.day, 0, 0, 0, timeZone);
  return toIsoTimestamp(instant);
}

/**
 * Local midnight on the calendar date `days` before `reference`'s local date.
 * `days` is a count of calendar dates, so a DST boundary does not change
 * which date is chosen.
 */
export function startOfLocalDayBefore(
  reference: Date,
  days: number,
  timeZone: string,
): IsoTimestamp {
  const parts = zoneParts(reference, timeZone);
  const shifted = shiftCalendarDate(parts.year, parts.month, parts.day, -days);
  const midnight = instantsOfWallTime(
    shifted.year,
    shifted.month,
    shifted.day,
    0,
    0,
    0,
    timeZone,
  );
  const instant =
    midnight[0] ??
    wallTimeToUtc(shifted.year, shifted.month, shifted.day, 0, 0, 0, timeZone);
  return toIsoTimestamp(instant);
}

/**
 * True once the workspace calendar day that contains `dueAt` has ended.
 * On that day itself the issue is not overdue, whatever time `dueAt` names.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  const dueDay = localDate(dueAt, timeZone);
  const referenceDay = localDate(toIsoTimestamp(reference), timeZone);
  return dueDay < referenceDay;
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The most recent instant at or before `reference` whose clock in `timeZone`
 * reads `hour:00:00`. Today's occurrence when it has already passed, otherwise
 * yesterday's. A skipped hour (DST spring-forward) is treated as not yet passed.
 */
function mostRecentLocalHour(reference: Date, hour: number, timeZone: string): Date {
  const parts = zoneParts(reference, timeZone);
  const today = instantsOfWallTime(
    parts.year,
    parts.month,
    parts.day,
    hour,
    0,
    0,
    timeZone,
  ).filter((instant) => instant.getTime() <= reference.getTime());
  if (today.length > 0) return today[today.length - 1] as Date;

  const prev = shiftCalendarDate(parts.year, parts.month, parts.day, -1);
  const yesterday = instantsOfWallTime(
    prev.year,
    prev.month,
    prev.day,
    hour,
    0,
    0,
    timeZone,
  ).filter((instant) => instant.getTime() <= reference.getTime());
  if (yesterday.length > 0) return yesterday[yesterday.length - 1] as Date;

  const older = shiftCalendarDate(prev.year, prev.month, prev.day, -1);
  const before = instantsOfWallTime(
    older.year,
    older.month,
    older.day,
    hour,
    0,
    0,
    timeZone,
  );
  if (before.length > 0) return before[before.length - 1] as Date;

  throw new RangeError(
    `No local ${hour}:00 at or before ${reference.toISOString()} in ${timeZone}`,
  );
}

/**
 * The digest window ending at the most recent local `hour:00` at or before
 * `reference`. It starts at the same local hour on the previous calendar day,
 * so a DST change makes the window 23 or 25 hours rather than a flat 24.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHour}`);
  }

  const end = mostRecentLocalHour(reference, digestHour, timeZone);
  const endParts = zoneParts(end, timeZone);
  const prev = shiftCalendarDate(endParts.year, endParts.month, endParts.day, -1);
  const starts = instantsOfWallTime(prev.year, prev.month, prev.day, digestHour, 0, 0, timeZone);
  const start = starts[0] ?? mostRecentLocalHour(new Date(end.getTime() - 1), digestHour, timeZone);

  return {
    start: toIsoTimestamp(start),
    end: toIsoTimestamp(end),
  };
}

