import {
  addDays,
  digestWindow,
  formatDate,
  formatRelative,
  isOverdue,
  now,
  parseIso,
} from "@/lib/date";

it("treats a null due date as never overdue", () => {
  expect(isOverdue(null, REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(true);
  expect(isOverdue(iso("2026-03-15T12:00:01.000Z"), REFERENCE)).toBe(false);
});

input.new_string:
it("treats a null due date as never overdue and waits until the due day has ended", () => {
  expect(isOverdue(null, REFERENCE)).toBe(false);
  // Same UTC day as the reference, whatever time dueAt names: not overdue yet.
  expect(isOverdue(iso("2026-03-15T00:00:00.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T12:00:01.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T23:59:59.000Z"), REFERENCE)).toBe(false);
  // The previous calendar day has ended.
  expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
  expect(isOverdue(iso("2026-03-14T00:00:00.000Z"), REFERENCE)).toBe(true);
});

it("reads the due calendar day on the workspace clock", () => {
  // 15:00Z is midnight at the start of 16 Mar in Tokyo. 16:00Z is still that day.
  const reference = new Date("2026-03-15T16:00:00.000Z");
  expect(isOverdue(iso("2026-03-15T15:00:00.000Z"), reference, "Asia/Tokyo")).toBe(false);
  expect(isOverdue(iso("2026-03-15T14:59:59.000Z"), reference, "Asia/Tokyo")).toBe(true);
});

it("names the local calendar date and the instant that day began", () => {
  expect(localDate(iso("2026-03-15T15:00:00.000Z"), "UTC")).toBe("2026-03-15");
  expect(localDate(iso("2026-03-15T15:00:00.000Z"), "Asia/Tokyo")).toBe("2026-03-16");
  expect(startOfLocalDay(REFERENCE, "UTC")).toBe("2026-03-15T00:00:00.000Z");
  expect(startOfLocalDay(new Date("2026-03-15T16:00:00.000Z"), "Asia/Tokyo")).toBe(
    "2026-03-15T15:00:00.000Z",
  );
  expect(startOfLocalDay(new Date("2026-03-15T12:00:00.000Z"), "Asia/Kolkata")).toBe(
    "2026-03-14T18:30:00.000Z",
  );
  // 30 calendar days before 15 Mar, local midnight, not 30×24h before noon.
  expect(startOfLocalDayBefore(REFERENCE, 30, "UTC")).toBe("2026-02-13T00:00:00.000Z");
  expect(startOfLocalDayBefore(REFERENCE, 30, "Asia/Tokyo")).toBe(
    "2026-02-12T15:00:00.000Z",
  );
});

