  it("rejects a digest hour outside 0-23", () => {
    expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
    expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
  });

  it("ends the digest window on the workspace clock and stretches across DST", () => {
    const tokyo = digestWindow(9, new Date("2026-03-15T00:30:00.000Z"), "Asia/Tokyo");
    expect(tokyo.end).toBe("2026-03-15T00:00:00.000Z");
    expect(tokyo.start).toBe("2026-03-14T00:00:00.000Z");

    // 08:00 the morning clocks spring forward is 23 hours after the previous 08:00.
    const spring = digestWindow(8, new Date("2026-03-08T13:00:00.000Z"), "America/New_York");
    expect(spring.end).toBe("2026-03-08T12:00:00.000Z");
    expect(spring.start).toBe("2026-03-07T13:00:00.000Z");

    // 08:00 the morning clocks fall back is 25 hours after the previous 08:00.
    const fall = digestWindow(8, new Date("2026-11-01T14:00:00.000Z"), "America/New_York");
    expect(fall.end).toBe("2026-11-01T13:00:00.000Z");
    expect(fall.start).toBe("2026-10-31T12:00:00.000Z");
  });
});

